settings.liquid:
{%- comment -%}
CURVJEANS — Black Friday Bundle Exclusive Message + Daily 24h Countdown
{%- endcomment -%}

{%- liquid
assign _lc = request.locale.iso_code | downcase

case _lc
  when 'nl'
    assign l_title = '🔥 Exclusieve Black Friday Deal'
    assign l_line1 = 'Deze bundel is nu scherper geprijsd dan ooit.'
    assign l_line2 = '(Uitgesloten van andere bundelkortingen)'
  when 'de'
    assign l_title = '🔥 Exklusiver Black Friday Deal'
    assign l_line1 = 'Dieses Bundle hat seinen eigenen niedrigsten Preis des Jahres.'
    assign l_line2 = '(Von Bundle-Rabatten ausgeschlossen.)'
  else
    assign l_title = '🔥 Black Friday Exclusive Deal'
    assign l_line1 = 'This bundle is now at its lowest price ever.'
    assign l_line2 = '(Excluded from other bundle discounts)'
endcase
-%}

<div class="cj-prebf-block">
  <div class="cj-prebf-head">
    <span class="cj-prebf-title">{{ l_title }}</span>

    <!-- INLINE COUNTDOWN -->
    <span id="cj-inline-countdown" class="cj-inline-countdown"></span>
  </div>

  <div class="cj-prebf-text">
    <p>{{ l_line1 }}</p>
    <p class="cj-prebf-sub">{{ l_line2 }}</p>
  </div>
</div>

<style>
  .cj-prebf-block {
    background: #F5F5F5;
    border: 1px dashed #D9D9D9;
    border-radius: 12px;
    padding: 12px 14px;
    margin-top: 10px;
  }

  .cj-prebf-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
    margin-bottom: 4px;
    flex-wrap: wrap;
  }

  .cj-prebf-title {
    font-size: 15px;
    font-weight: 800;
    color: #111;
  }

  .cj-inline-countdown {
    font-size: 14px;
    font-weight: 800;
    color: #C7332C; 
    letter-spacing: 0.3px;
  }

  .cj-sec {
    display: inline-block;
    animation: fadeSec 1s linear infinite;
  }

  @keyframes fadeSec {
    0% { opacity: 1; }
    50% { opacity: .55; }
    100% { opacity: 1; }
  }

  .cj-prebf-text p {
    margin: 0;
    font-size: 14px;
    line-height: 1.3;
    color: #444;
    font-weight: 500;
  }

  .cj-prebf-sub {
    font-size: 12px !important;
    color: #777 !important;
    margin-top: 3px !important;
  }

  @media (max-width: 600px) {
    .cj-prebf-title { font-size: 14px; }
    .cj-inline-countdown { font-size: 13px; }
    .cj-prebf-text p { font-size: 13px; }
    .cj-prebf-sub { font-size: 11px !important; }
  }
</style>

<script>
document.addEventListener("DOMContentLoaded", function() {

  /* ---------------------------
     DAILY RESET TARGET (MIDNIGHT)
  ----------------------------*/
  function getMidnightTimestamp() {
    const now = new Date();
    return new Date(now.getFullYear(), now.getMonth(), now.getDate() + 1, 0, 0, 0).getTime();
  }

  let endTime = getMidnightTimestamp();

  /* ---------------------------
     COUNTDOWN FORMATTER
  ----------------------------*/
  function updateTimer() {
    const timers = document.querySelectorAll("#cj-inline-countdown, #cj-inline-countdown-2");
    if (!timers.length) return;

    const now = Date.now();
    if (now >= endTime) endTime = getMidnightTimestamp();

    const diff = endTime - now;
    const h = Math.floor(diff / (1000 * 60 * 60)).toString().padStart(2, "0");
    const m = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60)).toString().padStart(2, "0");
    const s = Math.floor((diff % (1000 * 60)) / 1000).toString().padStart(2, "0");

    timers.forEach(el => {
      el.innerHTML = `${h}u ${m}m <span class="cj-sec">${s}s</span>`;
    });
  }

  updateTimer();
  setInterval(updateTimer, 1000);


  /* ---------------------------
     VARIANT CHANGE RECOVERY
     (WORKS ON ALL THEMES)
  ----------------------------*/

  // Dawn, Taste, Refresh, Sense
  document.body.addEventListener("variant:changed", function() {
    setTimeout(updateTimer, 50);
  });

  // Empire, Prestige, Booster, Motion
  document.body.addEventListener("product:variant-change", function() {
    setTimeout(updateTimer, 50);
  });

  // Fallback: reinitialize when ATC button section reloads
  document.body.addEventListener("click", function(e) {
    if (e.target.matches("select, input[type='radio']")) {
      setTimeout(updateTimer, 100);
    }
  });

});
</script>
